test-code.code:
@Service
class AService {
    @Value("\${batchService.http.url}")
    var url: String = "" // bad: @Value var with unguarded setter

    fun setUrlViolate(url: String) {
        this.url = url // unguarded accessor
    }
}

@Service
class GoodService {
    @Value("\${batchService.http.url}")
    var url: String = "" // good: @Value with no other assignment
}

class NotShared {
    var url: String = "" // good, not a singleton
}

@Service
@NotThreadSafe
class NotThreadSafeService {
    var url: String = "" // good, @NotThreadSafe
}

@Component
class GuardedService {
    @GuardedBy("this")
    var url: String = "" // good, guarded
}

@Service
class VolatileService {
    @Volatile var url: String = "" // good, volatile
}

@Component
class AutowiredService {
    @Autowired
    lateinit var restTemplate: Any // good, injected
}

@Service
class BadMutableDate {
    val date: java.util.Date = java.util.Date() // bad, Date is mutable even with val
}

@Component
class BadMutableMap {
    val map: java.util.HashMap<String, String> = java.util.HashMap() // bad, mutable
}

@Component
class GoodGuardedMap {
    @GuardedBy("this")
    val map: java.util.HashMap<String, String> = java.util.HashMap() // good, guarded
}

@Service
@Scope("request")
class RequestScoped {
    var url: String = "" // good, request scoped
}

@ConfigurationProperties(prefix = "app")
@Component
class AppConfig {
    var url: String = "" // good, ConfigurationProperties
}

@Service
class PostConstructService {
    var url: String = ""

    @PostConstruct
    fun init() {
        url = "http://example.com"
    }
}
